def _safe_float(
    value: Any,
    default: float = 0.0,
) -> float:
    """
    Convierte valores a float de forma segura.
    """

    try:
        return float(value or 0)

    except (TypeError, ValueError):
        return default


def _money(
    value: Any,
) -> str:
    """
    Formatea un valor como dinero.
    """

    return f"${_safe_float(value):,.2f}"


def _section_header(
    eyebrow: str,
    title: str,
    description: str,
) -> None:
    """
    Encabezado reutilizable renderizado como HTML real.
    """

    st.html(
        dedent(
            f"""
            <section class="ax-tool-hero">
                <div class="ax-tool-kicker">{html.escape(str(eyebrow))}</div>
                <div class="ax-tool-title">{html.escape(str(title))}</div>
                <div class="ax-tool-sub">{html.escape(str(description))}</div>
            </section>
            """
        )
    )


AI_AVATAR_BASE64 = ""
CHAT_BRAIN_IMAGE = "data:image/webp;base64,"


def _image_from_base64(value: str) -> Image.Image | None:
    try:
        payload = value
        if "," in payload and payload.strip().lower().startswith("data:image"):
            payload = payload.split(",", 1)[1]
        raw = base64.b64decode(payload)
        return Image.open(io.BytesIO(raw)).convert("RGB")
    except Exception:
        return None


def _resolve_user_avatar() -> Any:
    """
    Usa automáticamente la foto guardada en el perfil.
    """

    candidate_keys = (
        "profile_image",
        "profile_photo",
        "foto_perfil",
        "avatar",
        "avatar_url",
        "user_avatar",
        "user_photo",
        "photo_url",
        "profile_picture",
    )

    for key in candidate_keys:
        value = st.session_state.get(key)

        if value in (None, ""):
            continue

        if isinstance(value, Image.Image):
            return value

        if isinstance(value, (bytes, bytearray)):
            try:
                return Image.open(io.BytesIO(value)).convert("RGB")
            except Exception:
                continue

        if isinstance(value, str):
            if value.startswith("data:image") or len(value) > 500:
                decoded = _image_from_base64(value)
                if decoded is not None:
                    return decoded
            return value

    return None


def _resolve_ai_avatar() -> Image.Image:
    image = _image_from_base64(AI_AVATAR_BASE64)
    if image is None:
        image = Image.new("RGB", (512, 512), "#071020")
    return image


def _message_time() -> str:
    return datetime.now().strftime("%H:%M")


